        .slice(0, 3);

      const key = keywords[0] || 'general';
      if (!clusters[key]) {
        clusters[key] = [];
      }
      clusters[key].push(article);
    });

    return Object.entries(clusters)
      .sort((a, b) => b[1].length - a[1].length)
      .slice(0, 10);
  }, [filteredNews]);

