          )}

          {/* Portfolio View - NEW */}
          {activeView === 'portfolio' && (
            <div style={{ padding: '32px' }}>
              <h2 style={{
                fontSize: '20px',
                fontWeight: '600',
                color: theme.text,
                marginBottom: '24px'
