                          <div>
                            <div style={{
                              fontSize: '24px',
                              fontWeight: '700',
                              color: theme.text,
                              marginBottom: '4px'
                            }}>
                              {ticker.symbol}
                            </div>
                            <div style={{
                              fontSize: '13px',
                              color: theme.textSecondary
                            }}>
                              {ticker.name}
                            </div>
                          </div>
                          {hasPosition && pnl !== 0 && (
                            <div style={{ textAlign: 'right' }}>
                              <div style={{
                                fontSize: '20px',
                                fontWeight: '700',
                                color: pnl >= 0 ? theme.success : theme.danger
